"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[941],{76963:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"WeaponDebug","desc":"Hitbox/volume visualizer for tuning weapons, required by every weapon\\nhandler. Flip the single `ENABLED` flag below and save \u2014 Rojo syncs it in.\\nNo command bar, no attributes.\\n\\nWhen on, every weapon swing/shot draws a bright Neon box matching the exact\\nquery volume (green = the attack found a target, red = it whiffed) that\\nauto-removes after `LIFETIME` seconds, and prints a line to the console so\\nyou can confirm the code path ran even if the part is off-screen. Reused by\\nlater plans for gun rays / AOE spheres.","source":{"line":15,"path":"src/ReplicatedStorage/SharedModules/WeaponDebug.luau"}}')}}]);